'use strict';
async function reviewNewMovements(next){let groups=C.duplicateGroups(state,next);if(!groups.length)return next;let dialog=$('#duplicateModal');if(dialog.open)throw Error('Completa prima il controllo duplicati già aperto');return new Promise((resolve,reject)=>{let done=false;const cancel=()=>{if(done)return;done=true;dialog.close();let error=Error('Inserimento annullato durante il controllo duplicati');error.name='AbortError';reject(error)};$('#duplicateContent').innerHTML=`<form id="duplicateForm"><h2>Attenzione: possibili operazioni duplicate</h2><div class="duplicate-warning" role="alert"><b>${groups.length} operazioni da controllare prima del salvataggio.</b><p>Le righe non selezionate vengono escluse dall’inserimento; per una modifica viene conservato il dato precedente. Se si tratta di operazioni distinte, selezionale e giustifica il motivo. Per aggiungere articoli a un addebito esistente, annulla e scegli Collega al pagamento nella revisione del documento.</p></div><div class="toolbar"><button type="button" class="btn" id="excludeAllDuplicates">Escludi tutte le righe simili</button><button type="button" class="btn" id="keepAllDuplicates">Seleziona tutte come distinte</button></div><div class="duplicate-list">${groups.map(g=>`<article class="duplicate-warning"><label class="check"><input type="checkbox" name="keep" value="${esc(g.id)}"> Confermo che questa è un’operazione distinta</label><p><b>Da inserire:</b> ${esc(g.movement.date)} · ${euro(g.movement.amount)} · ${esc(g.movement.account)}<br>${esc(g.movement.description)}</p>${g.matches.slice(0,4).map(x=>`<p><b>Simile già registrata in data ${esc(x.movement.date)}:</b> ${euro(x.movement.amount)} · ${esc(x.movement.account)}<br>${esc(x.movement.description)}<br><small>${esc(x.reason)}</small></p>`).join('')}${g.matches.length>4?'<p>Altre '+(g.matches.length-4)+' corrispondenze simili.</p>':''}</article>`).join('')}</div><label>Giustificazione delle operazioni distinte selezionate<textarea name="reason" maxlength="1000" placeholder="Es. due acquisti distinti con lo stesso importo, verificati sui documenti"></textarea></label><p id="duplicateReasonError" class="duplicate-warning hidden" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" id="cancelDuplicates">Annulla inserimento</button><button class="btn primary" id="applyDuplicates">Applica scelte e salva</button></div></form>`;$('#excludeAllDuplicates').onclick=()=>$$('#duplicateForm [name=keep]').forEach(x=>x.checked=false);$('#keepAllDuplicates').onclick=()=>$$('#duplicateForm [name=keep]').forEach(x=>x.checked=true);$('#cancelDuplicates').onclick=cancel;dialog.oncancel=e=>{e.preventDefault();cancel()};$('#duplicateForm').onsubmit=e=>{e.preventDefault();try{let data=new FormData(e.target),result=C.applyDuplicateChoices(state,next,groups,data.getAll('keep'),data.get('reason'),new Date().toISOString());done=true;dialog.close();resolve(result)}catch(error){$('#duplicateReasonError').classList.remove('hidden');$('#duplicateReasonError').textContent=error.message}};dialog.showModal()})}
